function hasFortuneEffect(card){
  const text = getCardText(card);
  return /占い[:：]/.test(text) || text.includes('必中モード') || text.includes('超必中モード') || /占い効果/.test(text);
}
function isTwoChoiceFortuneCardV202(card){
  if(!card) return false;
  const text = getCardText(card);
  if(!/占い[:：]/.test(text)) return false;
  try{
    return parseLevelledEffectSegments(text, '占い').length >= 2;
  }catch(e){
    return /[①②]/.test(text);
  }
}
function countFortuneCardUseV202(source='占い'){
  const game = state.battle.game;
  if(!game?.player) return;
  game.player.totalFortuneEffectsUsed = Number(game.player.totalFortuneEffectsUsed || 0) + 1;
  game.player.fortuneUsedCount = game.player.totalFortuneEffectsUsed;
  game.player.fortuneCardsUsedThisTurn = Number(game.player.fortuneCardsUsedThisTurn || 0) + 1;
  battleLog(`${source}：占いカード使用回数 +1（合計${game.player.totalFortuneEffectsUsed}）。`);
}
function setFortuneModeV203(mode, source='占い', opts={}){
  const game = state.battle.game;
  if(!game?.player) return;
  if(mode === 'super'){
    game.player.fortuneMode = 'super';
    if(opts.permanent){
      game.player.permanentSuperFortune = true;
      game.player.fortuneModeUntil = '';
      battleLog(`${source}：この対戦中、永続の超必中モードになりました。`);
    }else if(!game.player.permanentSuperFortune){
      game.player.fortuneModeUntil = opts.until || '';
      battleLog(`${source}：超必中モードになりました。`);
    }else{
      game.player.fortuneModeUntil = '';
    }
    return;
  }
  if(mode === 'hit'){
    if(game.player.permanentSuperFortune || game.player.fortuneMode === 'super'){
      game.player.fortuneMode = 'super';
      game.player.fortuneModeUntil = game.player.permanentSuperFortune ? '' : game.player.fortuneModeUntil;
      battleLog(`${source}：既に超必中モードのため、必中には下がりません。`);
      return;
    }
    game.player.fortuneMode = 'hit';
    game.player.fortuneModeUntil = opts.until || '';
    battleLog(`${source}：必中モードになりました。`);
  }
}
function isSuperFortunePermanentV203(){
  return !!state.battle.game?.player?.permanentSuperFortune;
}

// v117: precise renkei/double attack + Grandmaz cost-copy + hard solo turn button
function hasInnateDoubleAttackV117(card){
  const text = getCardText(card);
  if(!text.includes('2回攻撃')) return false;
  // 「れんけい：2回攻撃を得る」は条件付きなので、初期キーワードにはしない。
  const renkeiDouble = /れんけい[:：]?[^。]*2回攻撃/.test(text);
  if(renkeiDouble && !/^[^。]*2回攻撃/.test(text.replace(/れんけい[:：]?[^。]*/g, ''))) return false;
  return true;
}
function addDiscountedCopyToHandV117(card, costDelta, source='効果'){
  const game = state.battle.game;
  if(!card || !game?.player) return false;
  if((game.player.hand || []).length >= 10){
    battleLog(`${source}：${card.name}は手札上限10枚のため破棄。`);
    return false;
  }
  const baseCost = Number(card.cost || 0);
  const copy = JSON.parse(JSON.stringify(card));
  copy.id = `copy_${card.id}_${Date.now()}_${safeRandomId('v117').slice(0,8)}`;
  copy.cost = Math.max(0, baseCost + Number(costDelta || 0));
  copy.originalCardId = card.id;
  copy.costDeltaApplied = Number(costDelta || 0);
  copy.flags ||= {};
  copy.flags.deckBuildable = false;
  copy.flags.generatedOrEvolved = true;
  copy.searchText = `${copy.searchText || ''} ${source} コスト変更 ${copy.cost}`.trim();
  state.allCards.push(copy);
  state.cards.push(copy);
  game.player.hand.push(copy.id);
  battleLog(`${source}：${card.name}を手札へ。コスト ${baseCost}→${copy.cost}。`);
  return true;
}
function triggerGrandmazTop3V117(source='グランマーズ'){
  const game = state.battle.game;
  if(game.grandmazChoiceOpen) return false;
  const top = (game.player.deck || []).slice(0,3).map((id,i)=>({id,i,card:byId(id)})).filter(x=>x.card);
  if(!top.length){ battleLog(`${source}：デッキがありません。`); return false; }
  game.grandmazChoiceOpen = true;
  openChoiceModal(`${source}：1枚を手札へ（コスト-2）`, top.map(x=>`${x.card.name} (${Math.max(0, Number(x.card.cost||0)-2)})`), (picked, i)=>{
    game.grandmazChoiceOpen = false;
    const item = top[i];
    if(!item?.card) return;
    // 見た3枚をデッキから抜く。選んだカードはコピーとして手札へ、残りはデッキ下。
    const seenIds = top.map(x=>x.id);
    const restIds = [];
    for(const id of seenIds){
      const idx = game.player.deck.indexOf(id);
      if(idx >= 0) game.player.deck.splice(idx,1);
      if(id !== item.id) restIds.push(id);
    }
    addDiscountedCopyToHandV117(item.card, -2, source);
    for(const id of restIds) game.player.deck.push(id);
    battleLog(`${source}：残りをデッキ下へ。`);
    renderBattleArena(); syncMyBattleState();
  }, {kind:'grandmazTop3V117'});
  return true;
}
function soloHardTurnSwitchV117(){
  const game = state.battle.game;
  if(!game || !isSoloTestMode()) return false;
  state.battle.matchLocked = false;
  $('battle-arena')?.classList.remove('battle-locked');
  const current = soloActiveSideV114();
  applyEndTurnEffectsForSideV121(current);
  processSideTurnEndV131(current);
  const next = current === 'player' ? 'enemy' : 'player';
  game.soloActiveSide = next;
  game.isMyTurn = true;
  game.turn = Number(game.turn || 1) + 1;
  clearPendingTargetsOnSoloTurnEndV119();
  game.selectedHandIndex = null;
  game.selectedAttacker = null;
  game.pendingGenericEffect = null;
  game.pendingHeroSkill = null;
  battleLog(`${soloSideNameV114(current)}ターン終了。${soloSideNameV114(next)}ターンへ。`);
  soloStartSideTurnV114(next);
  renderBattleArena();
  syncMyBattleState();
  return true;
}
function installSoloForceTurnButtonV117(){
  // v119: 中央の後付けターン切替ボタンは不要になったため表示しない
  const btn = $('solo-force-turn-btn');
  if(btn) btn.classList.add('hidden');
}


// v163: 絶好調の「初期キーワード」と「絶好調状態なら」を分けて扱う。
// 文面中に絶好調という文字があるだけでは、カード自身が絶好調を持つとは判定しない。
function hasInnateZekkochoV163(card){
  const text = String(getCardText(card) || '');
  return /(^|[、。]\s*)絶好調(?:[、。]|$)/.test(text);
}
function getZekkochoSelfConditionSpecV163(card){
  const text = String(getCardText(card) || '');
  const marker = 'このユニットが絶好調状態なら';
  const i = text.indexOf(marker);
  if(i < 0) return null;
  const body = text.slice(i + marker.length).split('。')[0];
  const atk = body.match(/攻撃力\s*[+＋]\s*(\d+)/);
  const hp = body.match(/HP\s*[+＋]\s*(\d+)/);
  return {
    attack:Number(atk?.[1] || 0),
    hp:Number(hp?.[1] || 0),
    taunt:body.includes('におうだち'),
    cannotAttackLeader:body.includes('敵リーダーを攻撃できない'),
    poisonOnDamage:body.includes('ダメージを与えたユニットを毒'),
    enemyTurnDamageIsOne:body.includes('相手のターン中') && body.includes('受けるダメージは1')
  };
}
function fixConditionalZekkochoKeywordFlagsV163(unit, card){
  if(!unit || !card) return;
  const text = String(getCardText(card) || '');
  const i = text.indexOf('このユニットが絶好調状態なら');
  if(i < 0) return;
  const before = text.slice(0, i);
  // 条件文の中で初めて得るキーワードは、常時キーワードとして残さない。
  if(!before.includes('におうだち')) unit.keywords.taunt = false;
  if(!before.includes('毒')) unit.grantsPoisonOnDamage = false;
}
function refreshZekkochoSelfConditionV163(unit, card=null){
  if(!unit) return;
  card ||= byId(unit.cardId);
  const spec = getZekkochoSelfConditionSpecV163(card);
  const oldAtk = Number(unit._zekkochoSelfAttackBonus || 0);
  const oldHp = Number(unit._zekkochoSelfHpBonus || 0);
  if(oldAtk) unit.attack -= oldAtk;
  if(oldHp){
    unit.maxHp -= oldHp;
    unit.hp = Math.min(unit.hp, unit.maxHp);
  }
  unit._zekkochoSelfAttackBonus = 0;
  unit._zekkochoSelfHpBonus = 0;
  if(unit._zekkochoSelfTauntApplied){
    unit.keywords.taunt = !!unit._zekkochoSelfTauntBefore;
    unit._zekkochoSelfTauntApplied = false;
  }
  if(unit._zekkochoSelfPoisonApplied){
    unit.grantsPoisonOnDamage = !!unit._zekkochoSelfPoisonBefore;
    unit._zekkochoSelfPoisonApplied = false;
  }
  unit._zekkochoCannotAttackLeader = false;
  unit._zekkochoEnemyDamageIsOne = false;
  if(!spec || !isZekkochoV134(unit)) return;
  if(spec.attack){
    unit.attack += spec.attack;
    unit._zekkochoSelfAttackBonus = spec.attack;
  }
  if(spec.hp){
    unit.hp += spec.hp;
    unit.maxHp += spec.hp;
    unit._zekkochoSelfHpBonus = spec.hp;
  }
  if(spec.taunt){
    unit._zekkochoSelfTauntBefore = !!unit.keywords.taunt;
    unit.keywords.taunt = true;
    unit._zekkochoSelfTauntApplied = true;
  }
  if(spec.poisonOnDamage){
    unit._zekkochoSelfPoisonBefore = !!unit.grantsPoisonOnDamage;
    unit.grantsPoisonOnDamage = true;
    unit._zekkochoSelfPoisonApplied = true;
  }
  if(spec.cannotAttackLeader) unit._zekkochoCannotAttackLeader = true;
  if(spec.enemyTurnDamageIsOne) unit._zekkochoEnemyDamageIsOne = true;
}
function isOpponentTurnForUnitV163(unit){
  const game = state.battle?.game;
  if(!game || !unit) return false;
  const isPlayerUnit = (game.player?.board || []).includes(unit);
  const activeSide = game.soloActiveSide || (game.isMyTurn ? 'player' : 'enemy');
  return isPlayerUnit ? activeSide === 'enemy' : activeSide === 'player';
}

function parseKeywordFlags(card){
  const fullText = getCardText(card);
  const text = fullText.includes('シンクロ') ? fullText.slice(0, fullText.indexOf('シンクロ')) : fullText;
  return {
    taunt: text.includes('におうだち'),
    haste: text.includes('速攻'),
    support: text.includes('おうえん'),
    snipe: text.includes('ねらい撃ち'),
    poison: text.includes('毒'),
    stealth: text.includes('ステルス'),
    seal: text.includes('封印'),
    darkRobe: text.includes('闇の衣'),
    conditionGood: hasInnateZekkochoV163(card),
    synchro: fullText.includes('シンクロ'),
    proficiency: fullText.includes('熟練度'),
    spellDamagePlus: text.includes('特技ダメージ＋') || text.includes('特技ダメージ+'),
    terrainSlip: fullText.includes('すべる床'),
    terrainTreasure: fullText.includes('宝箱'),
    terrainBarrier: fullText.includes('バリア床'),
    terrainBlade: fullText.includes('刃の紋章'),
    terrainMagic: fullText.includes('魔法陣'),
    terrainBlessing: fullText.includes('祝福の聖域'),
    terrainHappy: fullText.includes('しあわせの国'),
    terrainOracle: fullText.includes('天啓の神域'),
    apathy: text.includes('無気力状態'),
    piercing: text.includes('貫通') && !text.includes('超貫通'),
    superPiercing: text.includes('超貫通'),
    metal: text.includes('メタルボディ') && !text.includes('ハードメタルボディ'),
    hardMetal: text.includes('ハードメタルボディ'),
    doubleAttack: hasInnateDoubleAttackV117(card),
    firstStrike: text.includes('先制'),
    vanish: text.includes('消滅'),
    tensionLink: text.includes('テンションリンク'),
    skillLink: text.includes('スキルリンク'),
    deathrattle: text.includes('死亡時'),
    summon: text.includes('召喚時'),
    powerBadge: text.includes('パワフルバッジ') || text.includes('パワフルバッチ'),
    building: card?.cardType === '建物' || fullText.includes('耐久値') || fullText.includes('自分のターン終了時耐久値'),
    costBoost: fullText.includes('コスト-') || fullText.includes('コストを-') || fullText.includes('コストが') && fullText.includes('下がる'),
    move: fullText.includes('移動') || fullText.includes('前列') || fullText.includes('後列') || fullText.includes('1マス上') || fullText.includes('1マス下'),
    get: fullText.includes('GET'),
    bet: fullText.includes('BET'),
    dungeon: fullText.includes('ダンジョン'),
    choice: fullText.includes('選択'),
    fortune: hasFortuneEffect(card),
    synchro: fullText.includes('シンクロ'),
    renkei: fullText.includes('れんけい'),
    skillBoost: fullText.includes('スキルブースト')
  };
}

function summarizeKeywords(flags){
  const label = [];
  if(flags.taunt) label.push('仁王');
  if(flags.haste) label.push('速攻');
  if(flags.snipe) label.push('狙撃');
  if(flags.poison) label.push('毒');
  if(flags.piercing) label.push('貫通');
  if(flags.superPiercing) label.push('超貫');
  if(flags.metal) label.push('金属');
  if(flags.hardMetal) label.push('硬金');
  if(flags.stealth) label.push('隠密');
  if(flags.seal) label.push('封印');
  if(flags.conditionGood) label.push('絶好');
  if(flags.synchro) label.push('同調');
  if(flags.powerBadge) label.push('バッジ');
  if(flags.building) label.push('建物');
  return label.slice(0,2).join('/');
}



function makeTargetPayload(refObj={}){
  if(!refObj) return null;
  const game = state.battle.game;
  const side = refObj.side;
  if(side === 'playerLeader' || side === 'enemyLeader') return {type:'leader', side};
  if(side === 'player' || side === 'enemy'){
    const board = side === 'player' ? game.player.board : game.enemy.board;
    const unit = board?.[refObj.pos];
    return {type:'unit', side, pos:refObj.pos, unitId:unit?.id || '', cardId:unit?.cardId || '', name:unit?.name || ''};
  }
  if(side === 'playerEmpty' || side === 'enemyEmpty') return {type:'emptySlot', side:side.replace('Empty',''), pos:refObj.pos};
  return {...refObj};
}
function makeEmptySlotTargetPayload(side, pos){
  return {type:'emptySlot', side, pos};
}
function makeEffectTargetPayload(effect, target){
  return {
    effectKind: effect?.kind || '',
    source: effect?.source || effect?.name || '',
    target: makeTargetPayload(target)
  };
}
function emitTargetSelected(kind, target, extra={}){
  emitBattleEvent('targetSelected', {kind, target:makeTargetPayload(target), ...extra});
}
function emitEmptySlotSelected(kind, side, pos, extra={}){
  emitBattleEvent('targetSelected', {kind, target:makeEmptySlotTargetPayload(side, pos), ...extra});
}


function emitChoiceSelected(kind, title, options, index, value, extra={}){
  emitBattleEvent('choiceSelected', {
    kind,
    title,
    options: Array.isArray(options) ? options.map(String) : [],
    index:Number(index),
    value:String(value ?? ''),
    ...extra
  });
}

function cloneEventPayload(payload={}){
  const out = {};
  for(const [k,v] of Object.entries(payload || {})){
    if(k === 'unit' && v) out.unit = {id:v.id, cardId:v.cardId, name:v.name, attack:v.attack, hp:v.hp, maxHp:v.maxHp, statuses:v.statuses || [], keywords:v.keywords || {}};
    else if(k === 'targetUnit' && v) out.targetUnit = {id:v.id, cardId:v.cardId, name:v.name, attack:v.attack, hp:v.hp, maxHp:v.maxHp, statuses:v.statuses || [], keywords:v.keywords || {}};
    else if(k === 'attacker' && v) out.attacker = {id:v.id, cardId:v.cardId, name:v.name, attack:v.attack, hp:v.hp, maxHp:v.maxHp, statuses:v.statuses || [], keywords:v.keywords || {}};
    else if(k === 'weapon' && v) out.weapon = {name:v.name, attack:v.attack, durability:v.durability, maxDurability:v.maxDurability, cardText:v.cardText, noCounter:v.noCounter, snipe:v.snipe, doubleAttack:v.doubleAttack, attacksLeft:v.attacksLeft};
    else if(k === 'card' && v) out.card = {id:v.id, name:v.name, cardType:v.cardType, cost:v.cost, attack:v.attack, hp:v.hp};
    else if(typeof v !== 'function') out[k] = v;
  }
  return out;
}


// v246: duplicate-trigger guard.
// Several effects are now implemented in both older generic text parsers and newer official-DB handlers.
// These helpers make event-level hooks idempotent and keep explicit official handlers from falling through
// into broad text parsers that can double damage/draw/heal.
function v246StableEffectKeyPart(value){
  try{
    if(value == null) return '';
    if(typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') return String(value);
    if(Array.isArray(value)) return value.map(v246StableEffectKeyPart).join(',');
    if(typeof value === 'object'){
      if(value.id || value.cardId || value.name || value.pos != null || value.side) return [value.id,value.cardId,value.name,value.side,value.pos].filter(x=>x!=null).join(':');
      return Object.keys(value).sort().map(k=>`${k}:${v246StableEffectKeyPart(value[k])}`).join('|');
    }
    return String(value);
  }catch(e){ return ''; }
}
function v246EventGuard(type, payload={}, scope='event'){
  const game = state.battle?.game;
  if(!game) return true;
  game._v246EffectGuards ||= Object.create(null);
  const p = payload || {};
  // v247: 同じターンに同じカードを2回使う正規挙動を止めない。
  // まず emitBattleEvent が付与する _eventId を最優先のキーにする。
  // _eventId がない直呼びの場合は、payloadオブジェクト自体に短命IDを付与する。
  // これにより「同じpayload/同じeventの二重呼び」だけを止め、
  // 別アクションとしての同名カード2回目・同種ダメージ2回目は通す。
  if(!p._eventId && !p._v247GuardId && !p._dedupeKey){
    try{ Object.defineProperty(p, '_v247GuardId', { value:safeRandomId('guard'), enumerable:false, configurable:true }); }
    catch(e){ p._v247GuardId = safeRandomId('guard'); }
  }
  // _dedupeKey is used only for effects that must be once per turn/timing,
  // e.g. turn-end cores. It intentionally overrides unique event ids.
  const idKey = p._dedupeKey || p._eventId || p._v247GuardId;
  const key = [scope, type, idKey].filter(x=>x!=null).join('|');
  if(game._v246EffectGuards[key]){
    console.warn('v247 duplicate trigger skipped', key);
    return false;
  }
  game._v246EffectGuards[key] = 1;
  const keys = Object.keys(game._v246EffectGuards);
  if(keys.length > 400) for(const k of keys.slice(0, keys.length - 260)) delete game._v246EffectGuards[k];
  return true;
}
function v246CardNameSet(list){ return new Set(list); }
const V246_EXPLICIT_SUMMON_TEXT_CARDS = v246CardNameSet(['Sキラーマシン','あくまのきし','あくまのめだま','あくまのカガミ','あんこくまどう','おおにわとり','おにびドングリ','きめんどうし','きりかぶおばけ','しんりゅう','とうろうへい','むつでエビ','やみのとうぞく','りゅうせんし','アイスコンドル','アイスゴーレム','アイスボンバー','アイラ','アサシンクロー','アデン','アークマージ','イブール','ウルベア魔人兵','ウルベア魔神兵','エビルポット','エンゼルスライム','オルゴ・デミーラ：第3形態','カミュ','カンタダこぶん','カンダタこぶん','カーディナルナイト','キラーマシン2','キラーマシン２','クイーンスライム','グランマーズ','グリズリー','ゴルゴンゾーラ','ゴンズ','ゴールデンドラゴン','サタンパピー','サンディ','シャイニング','シルバーベア','ジゴック','ジャミ','スピニー','スピンサタン','スラッピー','ゾンビマスター','ダークプラネット','ツンドラキー','デスフラッター','デスマエストロ','デスマシーン','デビルロード','デュラハンナイト','ドラゴビショップ','ドラゴンソルジャー','ニセたいこう','ヒドラ','ピサロのてさき','ファイアボール','フォレストマスター','フライングデス','ヘルズクロウ','ホメロス','ホワイトパンサー','ポイズンキッス','マジックリップス','マッドファルコン','ミレーユ','ライアン','ラグアス王子','ルドマン','ルバンカ','ロミア','ワイトキング','修道院','卑劣などくやずきん','占い小屋','塔','妖魔軍王ブギー','少女マリベル','怪獣プスゴン','怪盗ポイックリン','怪蟲アラグネ','暗黒大樹の番人','歌姫のマポレーナ','武器屋','残響のようじゅつし','牢屋','稽古相手','覇海軍王ジャコラ','賢者ルシェンダ','運命の天使ラヴィエル','飛翔のガーゴイル','高潔な王パパス','魔王の書','黄金兵長']);
function v246ShouldSkipGenericSummonText(card){ return !!(card?.name && V246_EXPLICIT_SUMMON_TEXT_CARDS.has(card.name)); }
function v246ChoiceOrFortuneHandled(card){ return !!(card && (hasFortuneEffect(card) || String(getCardText(card)).includes('選択'))); }

function emitBattleEvent(type, payload={}){
  const game = state.battle.game;
  if(!game) return;
  game.events ||= [];
  const event = {
    id:`evt_${Date.now()}_${safeRandomId('rnd').slice(0,8)}`,
    type,
    turn: game.turn,
    playerId: state.playerId,
    payload: cloneEventPayload(payload)
  };
  game.events.push(event);
  if(game.events.length > 80) game.events.splice(0, game.events.length - 80);
  const handlerPayload = {...payload, _eventId:event.id};
  if(!state.battle.processingRemoteAction && ['choiceSelected','targetSelected','attackDeclared','damageApplied','counterDamage','attackResolved','cardPlayed','spellPlayed','unitSummoned','unitPutIntoPlay','afterAttack','unitDeath','betActivated','weaponEquipped','weaponAfterAttack','weaponBroken','turnStart','turnEnd','ownTurnStart','ownTurnEnd','opponentTurnStart','opponentTurnEnd'].includes(type)){
    pushBattleAction(type, event.payload);
  }

  switch(type){
    case 'choiceSelected': return handleChoiceSelectedEvent(handlerPayload);
    case 'targetSelected': return handleTargetSelectedEvent(handlerPayload);
    case 'turnStart': return handleTurnStartEvent(handlerPayload);
    case 'ownTurnStart': return handleOwnTurnStartEvent(handlerPayload);
    case 'ownTurnEnd': return handleOwnTurnEndEvent(handlerPayload);
    case 'opponentTurnStart': return handleOpponentTurnStartEvent(handlerPayload);
    case 'opponentTurnEnd': return handleOpponentTurnEndEvent(handlerPayload);
    case 'turnEnd': return handleTurnEndEvent(handlerPayload);
    case 'cardPlayed': return handleCardPlayedEvent(handlerPayload);
    case 'spellPlayed': return handleSpellPlayedEvent(handlerPayload);
    case 'unitSummoned': return handleUnitSummonedEvent(handlerPayload);
    case 'unitPutIntoPlay': return handleUnitPutIntoPlayEvent(handlerPayload);
    case 'attackDeclared': return handleAttackDeclaredEvent(handlerPayload);
    case 'damageApplied': return handleDamageAppliedEvent(handlerPayload);
    case 'counterDamage': return handleCounterDamageEvent(handlerPayload);
    case 'attackResolved': return handleAttackResolvedEvent(handlerPayload);
    case 'afterAttack': return handleAfterAttackEvent(handlerPayload);
    case 'unitDeath': return handleUnitDeathEvent(handlerPayload);
    case 'betActivated': return handleBetActivatedEvent(handlerPayload);
    case 'weaponEquipped': return handleWeaponEquippedEvent(handlerPayload);
    case 'weaponAfterAttack': return handleWeaponAfterAttackEvent(handlerPayload);
    case 'weaponBroken': return handleWeaponBrokenEvent(handlerPayload);
  }
}

function handleChoiceSelectedEvent(payload={}){
  // v76: 選択肢はactionLog/reducer用に記録。実処理は各効果側で実行済み。
}

