function summonRandomUnitAtPos(predicate, pos, side='player'){
  const pool = state.allCards.filter(c => c.cardType === 'ユニット' && predicate(c));
  if(!pool.length) return false;
  return summonCardAtPos(chooseRandom(pool), pos, side);
}
