    g.pendingGenericEffect = {kind:'v250BackRowDamage', amount:1, source:name, target:'unitAny', forceChoiceModal:true};
    openEffectTargetChoiceModalV208(g.pendingGenericEffect);
    battleLog('おおくちばし：後列ユニット1体を選んでください。');
