  const pick=chooseRandom(hits,'v236KouunOmamori',{}); if(pick && firstEmptyByOwnerPriorityV217('player')>=0){ g.player.deck.splice(pick.idx,1); v236PutCardIntoPlay(pick.card,'player',source); }
